import type { IndexEntry } from './route-registry';

export function normalisePrefix(prefix: string): string {
  const [pathPart] = (prefix || '/').split('?');
  const withoutTrailingSlash = pathPart.replace(/\/+$/, '');
  return withoutTrailingSlash || '/';
}

export function pagesUnderPrefix(prefix: string, entries: IndexEntry[]): IndexEntry[] {
  const base = normalisePrefix(prefix);
  if (base === '/') return [];

  const marker = `${base}/`;
  return entries
    .filter((entry) => entry.type === 'page' && !!entry.path)
    .filter((entry) => normalisePrefix(entry.path as string).startsWith(marker))
    .sort((a, b) => (a.path as string).localeCompare(b.path as string));
}
