import { notify } from 'src/components/notifications/notify';
import { api } from 'pages/APIs';
import { call_us } from 'src/utils/support_help';
import { copyToClipboard } from 'quasar';
export default {
  methods: {
    help_center() {
      window.open(api.support_ticket);
    },

    call_us() {
      window.open(api.support_ticket);
    },

    get_call_us_support_no() {
      return call_us;
    },

    copyText() {
      const call_us_support_no = this.get_call_us_support_no();
      if (call_us_support_no.trim().length > 0) {
        copyToClipboard(call_us_support_no).then(() => {
          notify.success('Copied!');
        });
      }
    },
  },
};
